// Chunk 51, e8b#1: a stranger's 5 ₳ of ADA alone at the public account's 0/0 that carries a reference script, or an
// inline datum nested past core's cbor::MAX_DEPTH (128), passes isCollateralShaped (coin-control.ts:184), which reads
// only the value and the tokens. With no collateral chosen, collateralOf takes it as the oldest pure 5 ₳, and after a
// reclaim it's the Collateral page's candidate, the only UTxO its Set offers. Every Lovejoin build from the public
// account then fails: WebAssembly's Coin::from_row puts the collateral through eval::resolve_row, which refuses both
// shapes. A session's collateral already leaves such a row out (sessions.ts collateralFits, independent review L20).
//
// Each case asserts what the wallet should do, so it fails today and passes once the public account's pick and the
// page's candidate share collateralFits' rule.
import { describe, expect, it } from "vitest";

import { bodyOutpoints } from "../src/background/cbor";
import type { KoiosUtxo } from "../src/background/koios";
import { SESSION_LOVEJOIN_PUBLIC } from "../src/background/lovejoin";
import { account, CHAINS, PASSWORD, publicFunded, type Tested } from "./chain-fixtures";
import { koiosPreprod, testBalances } from "./fakes";
import { ADA } from "./v2-pools";

const STRANGER = "d7".repeat(32);
const OWN_FIVE = `${"e5".repeat(32)}#0`; // publicFunded's own 5 ₳
const hexBytes = (hex: string) => Uint8Array.from(Buffer.from(hex, "hex"));

/** What a stranger can put on an output of 5 ₳ alone: a reference script (one the wallet can measure), or a deep datum. */
const SHAPES: Array<[string, Partial<KoiosUtxo>]> = [
  ["a reference script", { reference_script: { hash: "ab".repeat(28), size: 3, type: "timelock", bytes: "820080" } }],
  ["an inline datum 200 levels deep", { inline_datum: { bytes: `${"81".repeat(200)}00`, value: null } }],
];

/** The stranger's 5 ₳ at the 12-word account's 0/0, a block older than publicFunded's own 5 ₳. */
async function strangers(t: Tested, shape: Partial<KoiosUtxo>): Promise<void> {
  const [first] = Object.values(koiosPreprod.accounts)[0]!.account_utxos.filter((u) => BigInt(u.value) > 1_000_000_000n);
  const keyHash = await t.wallet.withKeys((keys) => keys.cardano.paymentKeyHash(0, 0));
  t.koios.addedToAccounts.push({
    ...first!,
    tx_hash: STRANGER,
    tx_index: 0,
    address: account(12).preprod.receive_0,
    value: "5000000",
    payment_cred: keyHash,
    asset_list: [],
    block_height: first!.block_height! - 1,
    ...shape,
  });
}

describe("r51 e8b#1: a stranger's 5 ₳ the wallet can't put up", CHAINS, () => {
  it.each(SHAPES)("with %s is neither the account's collateral nor the Collateral page's candidate", async (_, shape) => {
    const t = testBalances();
    await t.wallet.create(account(12).phrase, PASSWORD); // no 5 ₳ of its own
    await strangers(t, shape);
    await t.balances.get("preprod");
    // It was read: the account's list holds it.
    expect((await t.coins.lists("preprod")).cardano.some((u) => u.txHash === STRANGER)).toBe(true);

    // The wallet takes none by itself: there's no 5 ₳ a public mix could put up, so Set pays 5 ₳ to 0/0.
    expect(await t.coins.collateral("preprod")).toEqual({ state: "none", reclaimed: false });
    // Nor is it offered after a reclaim, where Set takes the candidate (Collateral.tsx:162-164).
    expect(await t.coins.reclaim("preprod")).toEqual({ state: "none", reclaimed: true });
  });

  it.each(SHAPES)("with %s leaves a public mix the account's own 5 ₳ to put up", async (_, shape) => {
    const t = await publicFunded();
    await strangers(t, shape);
    const mix = await t.lovejoin.publicBuild("preprod", 1, { pool: ADA });
    expect(mix.mixes).toBeGreaterThan(0);
    const kept = await t.wallet.withKeys(() =>
      t.session.get<{ chain: Array<{ kind: string; txCbor: string }> }>(SESSION_LOVEJOIN_PUBLIC),
    );
    for (const tx of kept!.chain.filter((x) => x.kind === "mix")) {
      expect(bodyOutpoints(hexBytes(tx.txCbor), 13)).toEqual([OWN_FIVE]);
    }
  });
});

// Chunk 51, finding e8b#2: Set collateral's payment withdraws all the account's staking rewards, and its review
// doesn't say so. Settings → Collateral, with no 5 ₳ UTxO held, builds a payment (Collateral.tsx `set` →
// "collateral-build" → send.ts `buildCollateral` → `pay`), which hands WebAssembly readAccount's `withdrawal` as every
// account payment does: with "Use staking rewards when spending" on (the default), the stake key registered and the
// vote delegated, that's the whole reward balance (account.ts `readAccount`), withdrawn into the change and signed for
// with the stake key (wasm `account_send`: `withdrawing`, `sign_staking`). Send, Make private and Create Seedelf show
// it on their reviews (ReviewTotals.tsx `RewardsRow`). The collateral review shows To, Address, Set aside, Fee and
// UTxOs spent, and its note says only the fee leaves. The right behaviour: the review says what it withdraws.
//
// The payment is built for real, over the house's fakes (the recorded 12-word account: 57.475311 ₳ of rewards, its
// vote on Always abstain), and its held transaction is read as Transaction details reads it. Then the review is
// rendered with React's server renderer, which has no DOM and can't press Set collateral, so the page's `summary`
// state starts as the built summary: the third useState of the render (useT's, the status, then the review's), as
// tests/swap-hidden-balances.test.ts seeds a form's.
import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, it, vi } from "vitest";

const seam = vi.hoisted(() => ({ initials: [] as unknown[], summary: undefined as unknown, seeded: false }));
vi.mock("react", async (original) => {
  const react = await original<typeof import("react")>();
  return {
    ...react,
    useState: (initial?: unknown) => {
      const before = seam.initials;
      seam.initials = [...before, initial];
      // Collateral's first states, in order: useT's redraw (0), the status, then the review's summary.
      const isSummary = before.length === 2 && before[0] === 0 && before[1] === undefined && initial === undefined;
      if (isSummary && seam.summary !== undefined && !seam.seeded) {
        seam.seeded = true;
        return react.useState(seam.summary);
      }
      return react.useState(initial);
    },
  };
});

const { txView } = await import("../src/background/tx-view");
const { t } = await import("../src/i18n");
const { DEFAULT_PREFERENCES } = await import("../src/shared/preferences");
const { NetworkContext } = await import("../src/ui/network");
const { PreferencesContext } = await import("../src/ui/preferences");
const { Collateral } = await import("../src/ui/screens/Collateral");
const { formatAda } = await import("../src/ui/format");
const { loadTestWasm, stakingPreprod, testBalances, vectors } = await import("./fakes");

const PASSWORD = "correct horse battery";
const phrase12 = vectors("cardano_account.json").find((v) => v.account === 0 && v.phrase.split(" ").length === 12)!;
const noop = () => undefined;
/** What a person reads of markup. */
const words = (html: string) =>
  html.replace(/<[^>]+>/g, " ").replaceAll("&#x27;", "'").replaceAll("&amp;", "&").replace(/\s+/g, " ").trim();

describe("Set collateral's review (chunk 51, e8b#2)", () => {
  it("says the staking rewards its payment withdraws, as every other public review does", async () => {
    // The 12-word account holds no 5 ₳ UTxO, so Set collateral is a payment, and its rewards can be withdrawn.
    const w = testBalances();
    await w.wallet.create(phrase12.phrase, PASSWORD);
    await w.balances.get("preprod");
    expect(await w.coins.collateral("preprod")).toEqual({ state: "none", reclaimed: false });
    expect((await w.preferences.get()).spendRewards).toBe(true);
    const stake = stakingPreprod.account_info.find((a) => a.stake_address === phrase12.preprod.stake)!;
    expect(stake).toMatchObject({ status: "registered", delegated_drep: "drep_always_abstain", rewards_available: "57475311" });

    // Built as the page's Set collateral builds it: 5 ₳ to the account's own 0/0, and the whole reward balance withdrawn.
    const summary = await w.send.buildCollateral("preprod");
    expect(summary.payments).toMatchObject([{ address: phrase12.preprod.receive_0, own: true, lovelace: "5000000", tokens: [] }]);
    expect(summary.withdrawal).toBe(stake.rewards_available);
    // What Send submits withdraws it: the held bytes, read as Transaction details reads them.
    const view = await txView({ wasm: loadTestWasm(), wallet: w.wallet, session: w.session }, "preprod", summary.txHash);
    expect(view.detail.withdrawals.map((x) => x.lovelace)).toEqual([stake.rewards_available]);

    // The review of that payment, as the page shows it once Set collateral has built it.
    seam.initials = [];
    seam.summary = summary;
    const html = renderToStaticMarkup(
      createElement(
        NetworkContext.Provider,
        { value: "preprod" },
        createElement(
          PreferencesContext.Provider,
          { value: { prefs: DEFAULT_PREFERENCES, loaded: true, set: async () => undefined } },
          createElement(Collateral, { onBack: noop }),
        ),
      ),
    );
    expect(seam.seeded, "Collateral's states moved: its review's summary wasn't the render's third useState").toBe(true);
    const review = words(html);
    expect(review).toContain(words(t("collateral.review.title")));
    expect(review).toContain(`${words(t("collateral.setAside"))} ${formatAda("5000000")} ₳`);
    // The 57.475311 ₳ it withdraws, which Send, Make private and Create Seedelf show (RewardsRow): nowhere here today.
    expect(review).toContain(formatAda(stake.rewards_available));
  });
});

// Chunk 51's whole review, e8b#3: Bring everything back's switch builds every return again (ClaimAll's `rebuild`),
// and a session the user taps to leave out while that build runs must stay out once it lands, and stay out of Send.
//
// The rebuild is an await, then a press after it, which the house seam (screens-wiring-review-fixes.test.ts) can't run
// ("What a press does after an await doesn't run here"). So this runs the real ClaimAll on React's own reconciler
// (react-dom/client, `act`), over the small DOM below: no new dependency. Clicks go through React's root listeners, so
// React's own rule for a disabled button (no onClick) holds as a browser's does. The worker is `call`, answered when
// the test says.
import { act, createElement } from "react";
import { afterEach, beforeAll, describe, expect, it, vi } from "vitest";

import type { SessionBackSummary, SessionView } from "../src/shared/rpc";

const worker = vi.hoisted(() => ({
  /** Every request the page made, in order, each answered when the test says. */
  waiting: [] as Array<{ type: string; payload: unknown; resolve: (value: unknown) => void }>,
}));

vi.mock("../src/ui/background", async (original) => ({
  ...(await original<typeof import("../src/ui/background")>()),
  call: (type: string, payload: unknown) => new Promise((resolve) => worker.waiting.push({ type, payload, resolve })),
}));

const { ClaimAll } = await import("../src/ui/screens/ClaimAll");

// ---------------------------------------------------------------------------------------------------------------
// A DOM just big enough for react-dom/client to render into and dispatch a click through.

const HTML_NS = "http://www.w3.org/1999/xhtml";
type Options = boolean | { capture?: boolean } | undefined;
const capturing = (o: Options) => (typeof o === "boolean" ? o : !!o?.capture);

class FakeEvent {
  target: FakeNode | null = null;
  currentTarget: unknown = null;
  defaultPrevented = false;
  stopped = false;
  readonly bubbles = true;
  readonly cancelable = true;
  readonly button = 0;
  readonly timeStamp = Date.now();
  constructor(readonly type: string) {}
  preventDefault() {
    this.defaultPrevented = true;
  }
  stopPropagation() {
    this.stopped = true;
  }
  stopImmediatePropagation() {
    this.stopped = true;
  }
}

type Handler = ((e: FakeEvent) => void) | { handleEvent(e: FakeEvent): void };

class FakeTarget {
  listeners: Array<{ type: string; fn: Handler; capture: boolean }> = [];
  addEventListener(type: string, fn: Handler, o?: Options) {
    this.listeners.push({ type, fn, capture: capturing(o) });
  }
  removeEventListener(type: string, fn: Handler, o?: Options) {
    const capture = capturing(o);
    this.listeners = this.listeners.filter((l) => !(l.type === type && l.fn === fn && l.capture === capture));
  }
  fire(event: FakeEvent, capture: boolean) {
    for (const l of this.listeners.filter((x) => x.type === event.type && x.capture === capture)) {
      if (typeof l.fn === "function") l.fn.call(this, event);
      else l.fn.handleEvent(event);
    }
  }
}

class FakeNode extends FakeTarget {
  parentNode: FakeNode | null = null;
  childNodes: FakeNode[] = [];
  nodeValue: string | null = null;
  constructor(
    readonly nodeType: number,
    readonly nodeName: string,
    public ownerDocument: FakeDocument | null,
  ) {
    super();
  }
  get firstChild() {
    return this.childNodes[0] ?? null;
  }
  get lastChild() {
    return this.childNodes[this.childNodes.length - 1] ?? null;
  }
  get nextSibling(): FakeNode | null {
    const siblings = this.parentNode?.childNodes;
    return siblings ? (siblings[siblings.indexOf(this) + 1] ?? null) : null;
  }
  get previousSibling(): FakeNode | null {
    const siblings = this.parentNode?.childNodes;
    return siblings ? (siblings[siblings.indexOf(this) - 1] ?? null) : null;
  }
  get parentElement() {
    return this.parentNode?.nodeType === 1 ? this.parentNode : null;
  }
  appendChild<T extends FakeNode>(child: T): T {
    return this.insertBefore(child, null);
  }
  insertBefore<T extends FakeNode>(child: T, before: FakeNode | null): T {
    child.parentNode?.removeChild(child);
    const at = before ? this.childNodes.indexOf(before) : -1;
    if (at < 0) this.childNodes.push(child);
    else this.childNodes.splice(at, 0, child);
    child.parentNode = this;
    return child;
  }
  removeChild<T extends FakeNode>(child: T): T {
    const at = this.childNodes.indexOf(child);
    if (at >= 0) this.childNodes.splice(at, 1);
    child.parentNode = null;
    return child;
  }
  contains(other: FakeNode | null) {
    for (let n = other; n; n = n.parentNode) if (n === this) return true;
    return false;
  }
  getRootNode(): FakeNode {
    let n: FakeNode = this;
    while (n.parentNode) n = n.parentNode;
    return n;
  }
  get textContent(): string {
    return this.nodeType === 3 ? (this.nodeValue ?? "") : this.childNodes.map((c) => c.textContent).join("");
  }
  set textContent(text: string) {
    if (this.nodeType === 3) {
      this.nodeValue = text;
      return;
    }
    for (const c of [...this.childNodes]) this.removeChild(c);
    if (text) this.appendChild(this.ownerDocument!.createTextNode(text));
  }
  /** Capture from the window down, then bubble back up, as a browser dispatches a click. */
  dispatchEvent(event: FakeEvent) {
    const path: FakeTarget[] = [];
    for (let n: FakeNode | null = this; n; n = n.parentNode) path.push(n);
    path.push(fakeWindow);
    event.target = this;
    for (const t of [...path].reverse()) {
      if (event.stopped) break;
      event.currentTarget = t;
      t.fire(event, true);
    }
    for (const t of path) {
      if (event.stopped) break;
      event.currentTarget = t;
      t.fire(event, false);
    }
    return !event.defaultPrevented;
  }
}

class FakeText extends FakeNode {
  constructor(text: string, doc: FakeDocument) {
    super(3, "#text", doc);
    this.nodeValue = text;
  }
  get data() {
    return this.nodeValue ?? "";
  }
  set data(text: string) {
    this.nodeValue = text;
  }
}

class FakeStyle {
  [name: string]: unknown;
  setProperty(name: string, value: string) {
    this[name] = value;
  }
  removeProperty(name: string) {
    delete this[name];
  }
  getPropertyValue(name: string) {
    return String(this[name] ?? "");
  }
}

class FakeElement extends FakeNode {
  readonly attributes = new Map<string, string>();
  readonly style = new FakeStyle();
  readonly tagName: string;
  readonly localName: string;
  scrollTop = 0;
  scrollLeft = 0;
  offsetHeight = 0;
  constructor(
    tag: string,
    doc: FakeDocument,
    readonly namespaceURI: string = HTML_NS,
  ) {
    super(1, namespaceURI === HTML_NS ? tag.toUpperCase() : tag, doc);
    this.tagName = this.nodeName;
    this.localName = tag;
  }
  setAttribute(name: string, value: unknown) {
    this.attributes.set(name, String(value));
  }
  setAttributeNS(_ns: string | null, name: string, value: unknown) {
    this.setAttribute(name, value);
  }
  getAttribute(name: string) {
    return this.attributes.get(name) ?? null;
  }
  hasAttribute(name: string) {
    return this.attributes.has(name);
  }
  removeAttribute(name: string) {
    this.attributes.delete(name);
  }
  removeAttributeNS(_ns: string | null, name: string) {
    this.removeAttribute(name);
  }
  focus() {}
  blur() {}
}

class FakeDocument extends FakeNode {
  readonly documentElement: FakeElement;
  readonly head: FakeElement;
  readonly body: FakeElement;
  activeElement: FakeElement | null = null;
  defaultView: unknown = null;
  constructor() {
    super(9, "#document", null);
    this.documentElement = this.appendChild(new FakeElement("html", this));
    this.head = this.documentElement.appendChild(new FakeElement("head", this));
    this.body = this.documentElement.appendChild(new FakeElement("body", this));
  }
  get scrollingElement() {
    return this.documentElement;
  }
  createElement(tag: string) {
    return new FakeElement(tag, this);
  }
  createElementNS(ns: string, tag: string) {
    return new FakeElement(tag, this, ns);
  }
  createTextNode(text: string) {
    return new FakeText(text, this);
  }
  createComment(text: string) {
    const c = new FakeNode(8, "#comment", this);
    c.nodeValue = text;
    return c;
  }
}

const fakeDocument = new FakeDocument();
const fakeHistory = {
  state: null as unknown,
  scrollRestoration: "auto",
  pushState(state: unknown) {
    this.state = state;
  },
  replaceState(state: unknown) {
    this.state = state;
  },
  back() {},
};
const fakeWindow = Object.assign(new FakeTarget(), {
  event: undefined,
  document: fakeDocument,
  history: fakeHistory,
  HTMLIFrameElement: class {},
  top: {},
  self: undefined as unknown,
  location: { protocol: "chrome-extension:", href: "chrome-extension://seedelf/index.html" },
});
fakeWindow.self = fakeWindow;
fakeDocument.defaultView = fakeWindow;

let createRoot: (container: unknown) => { render(node: unknown): void; unmount(): void };

beforeAll(async () => {
  vi.stubGlobal("window", fakeWindow);
  vi.stubGlobal("document", fakeDocument);
  vi.stubGlobal("history", fakeHistory);
  vi.stubGlobal("IS_REACT_ACT_ENVIRONMENT", true);
  const client = (await import("react-dom/client")) as unknown as { createRoot?: typeof createRoot; default?: { createRoot: typeof createRoot } };
  createRoot = client.createRoot ?? client.default!.createRoot;
});

afterEach(() => {
  worker.waiting.length = 0;
});

// ---------------------------------------------------------------------------------------------------------------
// The page: three sites' sessions, built through Lovejoin, then built again straight back.

const SITES = { 4: "app.example", 5: "dex.example", 6: "nft.example" } as const;

const session = (index: 4 | 5 | 6): SessionView => ({
  index,
  network: "preprod",
  address: "addr_test1" + "s".repeat(50),
  createdAt: 0,
  stage: "open",
  txs: [{ kind: "out", txHash: "ef".repeat(32), at: 0, confirmed: true }],
  holding: { lovelace: "25000000", tokens: [], utxos: 2 },
  site: { origin: `https://${SITES[index]}` },
});

const back = (index: number, hash: string, over: Partial<SessionBackSummary> = {}): SessionBackSummary => ({
  network: "preprod",
  index,
  txHash: hash.repeat(32),
  fee: "300000",
  lovelace: "5200000",
  tokens: [],
  depositOutputs: 1,
  inputs: 2,
  ...over,
});
const chain = (entry: string) => ({ boxes: 2, depth: 2, mixes: 8, fees: "8000000", txs: 10, delay: "1-6", entry: entry.repeat(32) });

const throughLovejoin = {
  returns: [back(4, "a4", { lovejoin: chain("e4") }), back(5, "a5", { lovejoin: chain("e5") }), back(6, "a6", { lovejoin: chain("e6") })],
  skipped: [],
};
const straightBack = { returns: [back(4, "b4"), back(5, "b5"), back(6, "b6")], skipped: [] };

const container = fakeDocument.body.appendChild(fakeDocument.createElement("div"));

const elements = (node: FakeNode): FakeElement[] =>
  node.childNodes.flatMap((c) => (c instanceof FakeElement ? [c, ...elements(c)] : []));
const byTestId = (id: string) => elements(container).find((e) => e.getAttribute("data-testid") === id);
const rows = () => elements(byTestId("claim-returns")!).filter((e) => e.localName === "button");
const row = (host: string) => rows().find((b) => b.textContent.includes(host))!;
const pressed = (e: FakeElement) => e.getAttribute("aria-pressed");
const theSwitch = () => byTestId("claim-way-switch")!;
const sendButton = () => elements(container).find((e) => e.localName === "button" && e.getAttribute("class") === "primary")!;
const backButton = () => elements(container).find((e) => e.localName === "button" && e.getAttribute("class") === "icon-button")!;

function click(e: FakeElement) {
  act(() => {
    e.dispatchEvent(new FakeEvent("click"));
  });
}

/** The worker answers the page's oldest unanswered `type`, and React draws what that brings. */
async function answer(type: string, value: unknown) {
  const at = worker.waiting.findIndex((w) => w.type === type);
  expect(at, `the page asked the worker for ${type}`).toBeGreaterThanOrEqual(0);
  const [asked] = worker.waiting.splice(at, 1);
  await act(async () => {
    asked!.resolve(value);
    await new Promise((done) => setTimeout(done, 0));
  });
}

describe("Bring everything back: a session left out while the switch builds them again (r51 e8b#3)", () => {
  it("keeps a session the user left out during the rebuild out once it lands, and out of Send", async () => {
    const root = createRoot(container);
    act(() => root.render(createElement(ClaimAll, { sessions: [session(4), session(5), session(6)], onBack: () => {}, onDone: () => {} })));
    await answer("session-claim-build", throughLovejoin);

    // Built through Lovejoin: all three picked, the switch on.
    expect(rows().map(pressed)).toEqual(["true", "true", "true"]);
    expect(sendButton().textContent).toBe("Send 3 returns");
    expect(theSwitch().getAttribute("aria-checked")).toBe("true");

    // Lovejoin off: every return is built again, straight back. While that runs, the switch, Back and Send are off.
    click(theSwitch());
    expect(worker.waiting.map((w) => w.payload)).toEqual([{ indexes: [4, 5, 6], direct: true }]);
    expect(theSwitch().hasAttribute("disabled")).toBe(true);
    expect(backButton().hasAttribute("disabled")).toBe(true);
    expect(sendButton().hasAttribute("disabled")).toBe(true);

    // The user taps the session they still use on dex.example, to leave it out. What the screen shows it did:
    click(row("dex.example"));
    const shownAfterTap = pressed(row("dex.example"));

    // The rebuild lands, straight back.
    await answer("session-claim-build", straightBack);
    expect(theSwitch().getAttribute("aria-checked")).toBe("false");

    // A tap the screen took stays taken: the review keeps the choice it showed.
    expect
      .soft(pressed(row("dex.example")), `dex.example's row read aria-pressed=${shownAfterTap} after the tap; the button now reads "${sendButton().textContent}"`)
      .toBe(shownAfterTap);

    // And Send sends what the user chose: dex.example's return only if it was still picked.
    click(sendButton());
    const submit = worker.waiting.find((w) => w.type === "session-claim-submit");
    const meant = shownAfterTap === "false" ? ["b4", "b6"] : ["b4", "b5", "b6"];
    expect(submit?.payload).toEqual({ txHashes: meant.map((h) => h.repeat(32)) });

    act(() => root.unmount());
  });
});

// Chunk 51, finding e9a#1 (reported too as e8b#6). A token's details offer Send and Make private or public whenever
// the side can pay at all (Home.tsx `tokenAction`), for every token Home lists, those whose every unit is in a locked
// UTxO included (Home lists `withComing(balances.<side>)`). The form is handed the side less what's locked (Home.tsx
