// ν μ η υ and then "v" "u" "n" "u"; and the Cherokee and Lisu letters that draw A and D aren't mapped at all. A
// stranger's token named "tUSDΜ" or "ᎪᎠᎪ" then keeps its own name and isn't marked as posing as tUSDM or ADA,
// in every text view, on Home and in a site's signing prompt; and a pool ticker so spelled isn't flagged as shared.
// The confusables are Unicode's (UTS #39 confusables.txt): 039C→M, 039D→N, 0397→H, 03A5→Y, 13AA→A, 13A0→D,
// A4EE→A, A4D3→D.
import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, it } from "vitest";

import type { DappTxSummary, TokenAmount } from "../src/shared/rpc";
import { nameSkeleton, sharedNames, sharing } from "../src/ui/format";
import { NetworkContext } from "../src/ui/network";
import { SignTx } from "../src/ui/screens/DappApprovals";
import { tokenAmountText, tokenText, viewToken } from "../src/ui/tokens";

const hex = (text: string) => Buffer.from(text, "utf8").toString("hex");
const STRANGER = "e675b46e4d2242c991a8932a99db3044e80515ae14b4c4ccf6b3f4c9";
const named = (name: string) => ({ policyId: STRANGER, assetName: hex(name) });

// Greek capitals that draw Latin letters, and the Cherokee and Lisu letters that draw A and D.
const ALPHA = "Α"; // Α, draws A: folds right today (α → "a")
const EPSILON = "Ε"; // Ε, draws E
const ETA = "Η"; // Η, draws H
const IOTA = "Ι"; // Ι, draws I
const KAPPA = "Κ"; // Κ, draws K
const MU = "Μ"; // Μ, draws M
const NU = "Ν"; // Ν, draws N
const UPSILON = "Υ"; // Υ, draws Y
const CHEROKEE_ADA = "ᎪᎠᎪ"; // ᎪᎠᎪ: Cherokee GO, A, GO
const LISU_ADA = "ꓮꓓꓮ"; // ꓮꓓꓮ: Lisu A, DA, A

// Each fake beside the name it draws.
const GREEK: Array<[string, string]> = [
  [`tUSD${MU}`, "tUSDM"],
  [`${MU}${IOTA}${NU}`, "MIN"],
  [`S${NU}${EPSILON}${KAPPA}`, "SNEK"],
  [`${ETA}OSKY`, "HOSKY"],
  [`${IOTA}${NU}D${UPSILON}`, "INDY"],
  [`USD${MU}`, "USDM"],
  [`${NU}U${NU}${ALPHA}`, "NUNA"],
];

const summary = (over: Partial<DappTxSummary>): DappTxSummary => ({
  txHash: "ab".repeat(32),
  fee: "180000",
  netLovelace: "-500000000",
  netTokens: [],
  spentLovelace: "500180000",
  returnedLovelace: "0",
  stakingLovelace: "0",
  ownInputs: 1,
  paid: [],
  ownOutputs: [],
  mint: [],
  certificates: [],
  withdrawals: [],
  collateral: null,
  scripts: false,
  referenceInputs: 0,
  votes: 0,
  proposals: [],
  donation: null,
  note: null,
  metadata: false,
  validFrom: null,
  validUntil: null,
  signs: ["0/0"],
  unknownInputs: [],
  othersSign: 0,
  complete: true,
  ...over,
});
const ADDRESS = "addr_test1qz2fxv2umyhttkxyxp8x0dlpdt3k6cwng5pxj3jhsydzer3jcu5d8ps7zex2k2xt3uqxgjqnnj83ws8lhrn648jjxtwq2ytjqp";
const text = (html: string) => html.replace(/<[^>]+>/g, " ").replace(/&#x27;/g, "'").replace(/\s+/g, " ");

describe("r51 e9b#1, the controls: what the check catches today", () => {
  it("folds Cyrillic М and Greek Α, and marks the tokens so named", () => {
    expect(nameSkeleton("tUSDМ")).toBe(nameSkeleton("tUSDM"));
    expect(tokenText("preprod", named("tUSDМ")).posesAs).toBe("tUSDM");
    expect(tokenText("preprod", named(`${ALPHA}D${ALPHA}`)).posesAs).toBe("ADA");
  });
});

describe("r51 e9b#1: a capital of another script that draws a Latin letter folds to it", () => {
  it("gives Greek capitals the skeleton of the Latin name they draw", () => {
    expect(GREEK.map(([fake]) => [fake, nameSkeleton(fake)])).toEqual(GREEK.map(([fake, real]) => [fake, nameSkeleton(real)]));
  });

  it("gives Cherokee and Lisu ADA the skeleton of ADA", () => {
    expect([CHEROKEE_ADA, LISU_ADA].map((fake) => [fake, nameSkeleton(fake)])).toEqual([
      [CHEROKEE_ADA, nameSkeleton("ADA")],
      [LISU_ADA, nameSkeleton("ADA")],
    ]);
  });

  it("marks a stranger's tUSDΜ and ΜΙΝ as posing as the listed tUSDM and MIN, and names them by fingerprint", () => {
    const fakes: Array<[string, string]> = [
      [`tUSD${MU}`, "tUSDM"],
      [`${MU}${IOTA}${NU}`, "MIN"],
    ];
    expect(fakes.map(([fake]) => [fake, tokenText("preprod", named(fake)).posesAs])).toEqual(fakes);
    for (const [fake, real] of fakes) {
      const t = tokenText("preprod", named(fake));
      expect(tokenAmountText("preprod", { ...named(fake), quantity: "10000" }), fake).toBe(
        `10,000 ${t.id} (not on the wallet's list: it calls itself ${fake}, but it isn't the listed ${real})`,
      );
    }
  });

  it("marks a stranger's Cherokee or Lisu ADA as posing as ADA", () => {
    for (const fake of [CHEROKEE_ADA, LISU_ADA]) {
      const t = tokenText("preprod", named(fake));
      expect(t, fake).toMatchObject({ label: t.id, listed: false, posesAs: "ADA", own: fake });
      expect(tokenAmountText("preprod", { ...named(fake), quantity: "1000" }), fake).toBe(
        `1,000 ${t.id} (not on the wallet's list: it calls itself ${fake}, but it isn't ADA)`,
      );
    }
  });

  it("gives Home's row for tUSDΜ the warning line, in the warning's colour", () => {
    const fake: TokenAmount = { ...named(`tUSD${MU}`), quantity: "10000", decimals: 0, fingerprint: "" };
    const view = viewToken("preprod", fake);
    expect({ label: view.label, sub: view.sub, warn: view.warn }).toEqual({
      label: tokenText("preprod", fake).id,
      sub: `Calls itself tUSD${MU}, not on the wallet's list`,
      warn: true,
    });
  });

  it("warns in a site's signing prompt that a token it gets is named like tUSDM", () => {
    const fake = { ...named(`tUSD${MU}`), quantity: "10000" };
    const html = renderToStaticMarkup(
      createElement(
        NetworkContext.Provider,
        { value: "preprod" },
        createElement(SignTx, {
          summary: summary({
            netTokens: [fake],
            paid: [{ address: ADDRESS, lovelace: "500000000", tokens: [], datum: null, script: false, seedelf: null, ownPaymentKey: false }],
          }),
          partial: false,
          session: false,
          collateralSpent: false,
        }),
      ),
    );
    const page = text(html);
    expect(page).not.toMatch(new RegExp(`Gets\\s+10,000 tUSD${MU}`));
    expect(html).toContain('data-testid="dapp-lookalike"');
  });

  it("counts a pool ticker in Greek capitals as sharing the Latin one's", () => {
    const pools = [{ ticker: "NUNA" }, { ticker: `${NU}U${NU}${ALPHA}` }];
    expect(sharing(sharedNames(pools, (p) => p.ticker), "NUNA")).toBe(2);
  });

  // Only a mainnet build carries the mainnet list (Vitest builds with the extension's own flags).
  (__MAINNET_ENABLED__ ? it : it.skip)("marks a stranger's SΝΕΚ, USDΜ and ΗOSKY as the listed mainnet tokens", () => {
    const fakes: Array<[string, string]> = [
      [`S${NU}${EPSILON}${KAPPA}`, "SNEK"],
      [`USD${MU}`, "USDM"],
      [`${ETA}OSKY`, "HOSKY"],
    ];
    expect(fakes.map(([fake]) => [fake, tokenText("mainnet", named(fake)).posesAs])).toEqual(fakes);
  });
});

// Chunk 51, finding e9b#2. Some warnings are shown in the warning's colour through a `--warn` class rather than
// inside <Callout tone="warn"> or a role="alert": an unlisted token passing for ADA or a listed token, in every review
// and site sign window and on Home; a pool that keeps all its rewards or is oversaturated; a pool's ticker or a DRep's
// name that another one uses too. scripts/i18n-critical.mjs (isCriticalElement) reads only callouts and alerts, and
// none of these keys is named `.warn.`, so they aren't in docs/i18n/critical-keys.json. tests/i18n.test.ts's
// verified-critical and negation gates then never look at them. Each element is rendered here with every English
// value marked by the key that made it, and every key with words of its own inside a `--warn` element has to be in
// the derived set. This holds whichever fix is made: isCriticalElement learning the class, or the keys renamed `.warn.`.
import { readFileSync } from "node:fs";

import { createElement, type ReactElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { afterAll, describe, expect, it } from "vitest";

import { criticalKeys } from "../scripts/i18n-critical.mjs";
import { i18n } from "../src/i18n/core";
import type { PoolRow, TokenAmount } from "../src/shared/rpc";
import { TokenAmountText, TokenRow } from "../src/ui/components/TokenList";
import { NetworkContext } from "../src/ui/network";
import { PoolListRow } from "../src/ui/screens/Pools";
import { DrepRow } from "../src/ui/screens/Voting";
import { viewToken } from "../src/ui/tokens";

const en: Record<string, string> = JSON.parse(
  readFileSync(new URL("../src/i18n/translations/en.json", import.meta.url), "utf8"),
);
const CRITICAL = new Set(criticalKeys(Object.keys(en)));
const baseOf = (key: string) => key.replace(/_(few|many|one|other|two|zero)$/, "");

// A language whose every value is English's, wrapped in its own key with its placeholders kept: ⟦key¦value⟧.
const MARKED = "x-keys";
i18n.addResourceBundle(
  MARKED,
  "translation",
  Object.fromEntries(Object.entries(en).map(([k, v]) => [k, `⟦${k}¦${v}⟧`])),
);
const KEY_MARK = /⟦([^¦⟧]+)¦/g;

afterAll(async () => {
  await i18n.changeLanguage("en");
});

const hex = (text: string) => Buffer.from(text, "utf8").toString("hex");
const STRANGER = "e675b46e4d2242c991a8932a99db3044e80515ae14b4c4ccf6b3f4c9";
const named = (name: string) => ({ policyId: STRANGER, assetName: hex(name) });
const noop = () => undefined;
const pool: PoolRow = {
  id: "pool1abcdefghijklmnopqrstuvwxyz0123456789abcdefghijklm",
  ticker: "LOGIC",
  margin: 1,
  cost: "340000000",
  pledge: "1000000000",
  stake: "5000000000000",
  saturation: 120,
};
const fakeAda: TokenAmount = { ...named("₳"), quantity: "5", decimals: 0, fingerprint: "" };

/** What shows each warning, made in the language that's on: a token's view takes its words when it's made. */
const elements = (): Array<[string, ReactElement]> => [
  ["a review's token passing for a listed one", createElement(TokenAmountText, { token: named("TUSDM"), amount: "500" })],
  ["a review's token passing for ADA", createElement(TokenAmountText, { token: named("₳"), amount: "5" })],
  ["Home's row of a token passing for ADA", createElement(TokenRow, { view: viewToken("preprod", fakeAda), onOpen: noop })],
  ["a pool's row in the list", createElement(PoolListRow, { pool, current: false, shared: true, onOpen: noop })],
  [
    "a DRep's row in the list",
    createElement(DrepRow, {
      drep: { id: "drep1y296z8tm7y7elwsmsewn4q2tdr5gu0fqztq97yttlpv7zycvsl554", name: "8Ball" },
      shared: true,
      disabled: false,
      onPick: noop,
    }),
  ],
];

/** Each element whose class has a `--warn` modifier: the warning's colour, with no callout or alert around it. */
const WARN = /<(\w+) class="([^"]*--warn\b[^"]*)"[^>]*>([^<]*)<\/\1>/g;
const decode = (html: string) =>
  html.replace(/&#x27;/g, "'").replace(/&quot;/g, '"').replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&amp;/g, "&");
const warningsIn = (element: ReactElement) =>
  [...renderToStaticMarkup(createElement(NetworkContext.Provider, { value: "preprod" }, element)).matchAll(WARN)].map(
    (m) => ({ cls: m[2]!, text: decode(m[3]!) }),
  );

/** A key with words of its own, not a frame such as `{{text}}.` whose words are all its values'. */
const hasWords = (key: string) => /\p{L}/u.test((en[key] ?? "").replace(/\{\{[^}]*\}\}/g, ""));

describe("r51 e9b#2: a warning in the warning's colour, with no callout around it", () => {
  it("is what each of these elements shows", async () => {
    await i18n.changeLanguage("en");
    expect(elements().map(([what, element]) => [what, warningsIn(element).map((w) => w.text)])).toEqual([
      ["a review's token passing for a listed one", ["Not on the wallet's list: it calls itself TUSDM, but it isn't the listed tUSDM."]],
      ["a review's token passing for ADA", ["Not on the wallet's list: it calls itself ₳, but it isn't ADA."]],
      ["Home's row of a token passing for ADA", ["Calls itself ₳, not on the wallet's list"]],
      ["a pool's row in the list", ["Shared ticker", "Keeps all rewards", "Oversaturated"]],
      ["a DRep's row in the list", ["Shared name"]],
    ]);
  });

  it("has every key with words of its own in the accuracy-critical set, so no draft of it ships unchecked", async () => {
    await i18n.changeLanguage(MARKED);
    const shown: string[] = [];
    const unchecked: string[] = [];
    for (const [what, element] of elements()) {
      for (const { cls, text } of warningsIn(element)) {
        for (const [, key] of text.matchAll(KEY_MARK)) {
          shown.push(key!);
          if (hasWords(key!) && !CRITICAL.has(baseOf(key!))) unchecked.push(`${baseOf(key!)}: ${what}, class "${cls}"`);
        }
      }
    }
    // Seven warnings, and every one read through its key: a test that reads nothing can't pass.
    expect(shown.filter(hasWords).length, JSON.stringify(shown)).toBeGreaterThanOrEqual(7);
    expect([...new Set(unchecked)].sort()).toEqual([]);
  });
});

// Chunk 51, b1#1. licenses/THIRD-PARTY.txt is one of the store zip's files:
// scripts/package.mjs writes thirdParty()'s text into dist/ and zips every file
// there, and releases.md says the same commit gives the same zip. So the notices
// must be the same text whatever locale the packaging shell has. third-party.mjs
// sorts each group with localeCompare and no locale, which takes the shell's
// (LC_ALL, then LC_MESSAGES, then LANG). Each case runs thirdParty() in a fresh
// node with that locale, as `npm run package` would, and compares it with C's.
// Each run asks cargo for the module's crates, offline (CARGO_NET_OFFLINE).

import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { fileURLToPath, pathToFileURL } from "node:url";

import { beforeAll, describe, expect, it } from "vitest";

const extension = fileURLToPath(new URL("..", import.meta.url));
const script = pathToFileURL(fileURLToPath(new URL("../scripts/third-party.mjs", import.meta.url))).href;

/** thirdParty("1.9.1").text, from a fresh node whose locale is `locale`. */
function noticesIn(locale: string): string {
  const env: NodeJS.ProcessEnv = { ...process.env, LC_ALL: locale, CARGO_NET_OFFLINE: "true", RUSTUP_AUTO_INSTALL: "0" };
  delete env.NODE_OPTIONS;
  const code = `import { thirdParty } from ${JSON.stringify(script)}; process.stdout.write(thirdParty("1.9.1").text);`;
  return execFileSync(process.execPath, ["--input-type=module", "-e", code], {
    cwd: extension,
    env,
    encoding: "utf8",
    maxBuffer: 64 << 20,
    timeout: 180_000,
  });
}

/** The notices' component lists: everything before the licence texts. */
const listing = (text: string) => text.slice(0, text.indexOf("Licence texts")).split("\n");
const sha256 = (text: string) => createHash("sha256").update(text).digest("hex");

describe("the store zip's third-party notices", () => {
  let reference = "";
  beforeAll(() => {
    reference = noticesIn("C");
  }, 180_000);

  it.each(["en_US.UTF-8", "et_EE.UTF-8", "lt_LT.UTF-8", "lv_LV.UTF-8", "cs_CZ.UTF-8", "sk_SK.UTF-8", "cy_GB.UTF-8", "th_TH.UTF-8"])(
    "are the same text in %s as in C",
    (locale) => {
      const text = noticesIn(locale);
      expect(listing(text)).toEqual(listing(reference));
      expect(sha256(text)).toBe(sha256(reference));
    },
    180_000,
  );
});

// Chunk 51, b1#2. wasm/build.sh builds the store's WebAssembly with whatever Rust rustup picks, and never checks
// or says which. rustup's order is +toolchain, then RUSTUP_TOOLCHAIN, then a directory override, then the nearest
// rust-toolchain.toml from the working folder up, then the default. So a release shell that sets RUSTUP_TOOLCHAIN
// builds the module with another Rust. build.sh's last lines, which are what the release record copies, name only
// the C compiler. part 2's second build runs in the same terminal, gets the same variable and agrees.
//
// The reachable case is narrower than "any installed toolchain". Here 1.96.x and nightly have no wasm32 target, and
// cargo refuses 1.90.0 and 1.93.0 because uplc@1.1.23 needs rustc 1.94.1. So it takes a toolchain other than the pin
// that has the target and rustc >= 1.94.1. `stable` has the target, and after a `rustup update` it is a later Rust.
// That is the case below: RUSTUP_TOOLCHAIN=stable, with stable at 1.99.0.
//
// This runs a copy of TREE's build.sh, in a scratch mirror of the workspace that holds the real Cargo.lock and
// rust-toolchain.toml. Stand-ins replace rustc, cargo, rustup, wasm-bindgen, clang and llvm-ar, and pick the
// toolchain in rustup's order. Nothing is compiled and nothing under TREE is written. The right behaviour: build.sh
// refuses a Rust other than the pinned one, builds with the pinned one anyway, or names the one it built with.

import { spawnSync } from "node:child_process";
import { chmodSync, copyFileSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

import { afterAll, expect, it } from "vitest";

const wasm = fileURLToPath(new URL("../../wasm/", import.meta.url));
const platform = fileURLToPath(new URL("../../../", import.meta.url));

const lock = readFileSync(join(platform, "Cargo.lock"), "utf8");
const pinned = /^channel\s*=\s*"([^"]+)"/m.exec(readFileSync(join(platform, "rust-toolchain.toml"), "utf8"))?.[1];
const bindgen = /^name = "wasm-bindgen"\nversion = "([^"]+)"/m.exec(lock)?.[1];
/** What `stable` resolves to once a `rustup update` has moved it past the pin. */
const LATER_STABLE = "1.99.0";

/** A bash script as written, raw: its `${…}` are spelled `@{…}` here so the template literal leaves them alone. */
function sh(strings: TemplateStringsArray): string {
  return strings.raw.join("").replaceAll("@{", "${");
}

const RESOLVE = sh`# rustup's choice: +toolchain, RUSTUP_TOOLCHAIN, the nearest rust-toolchain.toml up from the working
# folder, the default. (A directory override would come before the file; none is set here.)
toolchain() {
  if [[ "@{1:-}" == +* ]]; then echo "@{1#+}"; return; fi
  if [[ -n "@{RUSTUP_TOOLCHAIN:-}" ]]; then echo "$RUSTUP_TOOLCHAIN"; return; fi
  local d="$PWD"
  while :; do
    if [[ -f "$d/rust-toolchain.toml" ]]; then sed -n 's/^channel = "\(.*\)"$/\1/p' "$d/rust-toolchain.toml"; return; fi
    [[ "$d" == / ]] && break
    d="$(dirname "$d")"
  done
  echo "$FAKE_DEFAULT"
}
release_of() { case "$1" in stable) echo "$FAKE_STABLE" ;; *) echo "$1" ;; esac; }
# Each release its own commit, as each official toolchain has.
hash_of() { printf '%040d' "$(printf '%s' "$1" | cksum | cut -d' ' -f1)"; }
`;

const RUSTC = sh`#!/usr/bin/env bash
. "$(dirname "$0")/resolve.sh"
tc="$(toolchain "$@")"; [[ "@{1:-}" == +* ]] && shift
r="$(release_of "$tc")"; h="$(hash_of "$r")"
a=" $* "
if [[ "$a" == *" --print sysroot "* || "$a" == *" --print=sysroot "* ]]; then echo "$FAKE_ROOT/toolchains/$tc-x86_64-unknown-linux-gnu"; exit 0; fi
if [[ "$a" == *" -vV "* || "$a" == *" -Vv "* || ( "$a" == *" -V "* || "$a" == *" --version "* ) && ( "$a" == *" -v "* || "$a" == *" --verbose "* ) ]]; then
  printf 'rustc %s (%s 2026-01-01)\nbinary: rustc\ncommit-hash: %s\ncommit-date: 2026-01-01\nhost: x86_64-unknown-linux-gnu\nrelease: %s\nLLVM version: 21.1.8\n' "$r" "@{h:0:9}" "$h" "$r"
  exit 0
fi
if [[ "$a" == *" -V "* || "$a" == *" --version "* ]]; then echo "rustc $r (@{h:0:9} 2026-01-01)"; exit 0; fi
echo "stand-in rustc: not made for: $*" >&2; exit 2
`;

const CARGO = sh`#!/usr/bin/env bash
. "$(dirname "$0")/resolve.sh"
tc="$(toolchain "$@")"; [[ "@{1:-}" == +* ]] && shift
r="$(release_of "$tc")"; h="$(hash_of "$r")"
case "@{1:-}" in
  -V|--version) echo "cargo $r (@{h:0:9} 2026-01-01)"; exit 0 ;;
  build) shift ;;
  *) echo "stand-in cargo: not made for: $*" >&2; exit 2 ;;
esac
profile=dev; target=""
while [[ $# -gt 0 ]]; do
  case "$1" in
    --profile) profile="$2"; shift 2 ;;
    --profile=*) profile="@{1#*=}"; shift ;;
    --target) target="$2"; shift 2 ;;
    --target=*) target="@{1#*=}"; shift ;;
    --manifest-path) shift 2 ;;
    *) shift ;;
  esac
done
out="@{CARGO_TARGET_DIR:-$FAKE_WORKSPACE/target}/$target/$profile"
mkdir -p "$out"
# A module whose std names its compiler's commit, as a real one does (/rustc/<commit-hash>/library/...).
printf '\0asm\1\0\0\0/rustc/%s/library/core/src/panicking.rs' "$h" > "$out/seedelf_wasm.wasm"
echo "$r $h" >> "$FAKE_LOG"
echo "   Compiling seedelf-wasm v0.7.0 (/seedelf-platform/seedelf-web-wallet/wasm)" >&2
echo "    Finished \`$profile\` profile [optimized] target(s) in 0.01s" >&2
`;

const RUSTUP = sh`#!/usr/bin/env bash
. "$(dirname "$0")/resolve.sh"
if [[ "@{1:-}" == show && "@{2:-}" == active-toolchain ]]; then echo "$(toolchain)-x86_64-unknown-linux-gnu"; exit 0; fi
if [[ "@{1:-}" == run && $# -ge 3 ]]; then tc="$2"; shift 2; RUSTUP_TOOLCHAIN="$tc" exec "$@"; fi
echo "stand-in rustup: not made for: $*" >&2; exit 2
`;

const WASM_BINDGEN = sh`#!/usr/bin/env bash
if [[ "@{1:-}" == --version || "@{1:-}" == -V ]]; then echo "wasm-bindgen $FAKE_BINDGEN"; exit 0; fi
out=""; in=""
while [[ $# -gt 0 ]]; do
  case "$1" in
    --out-dir) out="$2"; shift 2 ;;
    --target|--out-name) shift 2 ;;
    --*) shift ;;
    *) in="$1"; shift ;;
  esac
done
mkdir -p "$out" && cp "$in" "$out/seedelf_wasm_bg.wasm" && : > "$out/seedelf_wasm.js"
`;

const roots: string[] = [];
afterAll(() => {
  for (const root of roots) rmSync(root, { recursive: true, force: true });
});

interface Run {
  status: number | null;
  output: string;
  /** The Rust the stand-in cargo built the module with, if it ran. */
  builtWith?: { release: string; hash: string };
}

/** TREE's build.sh, run as `npm run build:wasm` runs it (from extension/), in a fresh mirror, with `extra` in its shell. */
function build(extra: Record<string, string>): Run {
  const root = mkdtempSync(join(tmpdir(), "r51-b1-2-"));
  roots.push(root);
  const workspace = join(root, "seedelf-platform");
